//! Approximate zone of a pin: the municipality it falls in, from the outlines
//! in `data/zones.geojson` (generated by `scripts/prepare_zones.py` from
//! OpenStreetMap). The channel shows this instead of the exact location.

use anyhow::{Context, bail};
use geo::{Contains, Coord, LineString, MultiPolygon, Polygon};
use serde::Deserialize;

use crate::domain::request::Point;

#[derive(Debug, Clone)]
struct Zone {
    municipality: String,
    area: MultiPolygon<f64>,
}

#[derive(Debug, Clone, Default)]
pub struct Zones(Vec<Zone>);

#[derive(Deserialize)]
struct Collection {
    features: Vec<Feature>,
}

#[derive(Deserialize)]
struct Feature {
    properties: Properties,
    geometry: Geometry,
}

#[derive(Deserialize)]
struct Properties {
    municipality: String,
}

/// Rings are lists of `[lon, lat]`; the first ring of a polygon is its outline,
/// the rest are holes.
#[derive(Deserialize)]
#[serde(tag = "type", content = "coordinates")]
enum Geometry {
    Polygon(Vec<Vec<[f64; 2]>>),
    MultiPolygon(Vec<Vec<Vec<[f64; 2]>>>),
}

impl Zones {
    /// The outlines compiled into the binary.
    pub fn bundled() -> anyhow::Result<Zones> {
        Zones::parse(include_str!("../../data/zones.geojson")).context("data/zones.geojson")
    }

    fn parse(geojson: &str) -> anyhow::Result<Zones> {
        let collection: Collection = serde_json::from_str(geojson)?;
        let zones = collection
            .features
            .into_iter()
            .map(|f| {
                let polygons = match f.geometry {
                    Geometry::Polygon(rings) => vec![polygon(rings)?],
                    Geometry::MultiPolygon(parts) => parts
                        .into_iter()
                        .map(polygon)
                        .collect::<anyhow::Result<_>>()?,
                };
                Ok(Zone {
                    municipality: f.properties.municipality,
                    area: MultiPolygon(polygons),
                })
            })
            .collect::<anyhow::Result<_>>()?;
        Ok(Zones(zones))
    }

    /// The municipalities, in the file's (alphabetical) order.
    pub fn names(&self) -> Vec<&str> {
        self.0.iter().map(|z| z.municipality.as_str()).collect()
    }

    /// The municipality containing the pin, or `None` outside all of them.
    pub fn municipality(&self, p: Point) -> Option<&str> {
        let coord = Coord { x: p.lon, y: p.lat };
        self.0
            .iter()
            .find(|z| z.area.contains(&coord))
            .map(|z| z.municipality.as_str())
    }
}

fn polygon(rings: Vec<Vec<[f64; 2]>>) -> anyhow::Result<Polygon<f64>> {
    let mut rings = rings.into_iter().map(|ring| {
        LineString::from(
            ring.into_iter()
                .map(|[x, y]| Coord { x, y })
                .collect::<Vec<_>>(),
        )
    });
    let Some(exterior) = rings.next() else {
        bail!("polygon without rings");
    };
    Ok(Polygon::new(exterior, rings.collect()))
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Two unit squares side by side; the second has a hole in the middle.
    const SAMPLE: &str = r#"{"type":"FeatureCollection","features":[
        {"type":"Feature","properties":{"province":"P","municipality":"West"},
         "geometry":{"type":"Polygon","coordinates":[[[0,0],[1,0],[1,1],[0,1],[0,0]]]}},
        {"type":"Feature","properties":{"province":"P","municipality":"East"},
         "geometry":{"type":"MultiPolygon","coordinates":[[[[1,0],[2,0],[2,1],[1,1],[1,0]],
            [[1.4,0.4],[1.6,0.4],[1.6,0.6],[1.4,0.6],[1.4,0.4]]]]}}]}"#;

    fn at(lon: f64, lat: f64) -> Point {
        Point { lat, lon }
    }

    #[test]
    fn finds_the_containing_municipality() {
        let zones = Zones::parse(SAMPLE).unwrap();
        assert_eq!(zones.municipality(at(0.5, 0.5)), Some("West"));
        assert_eq!(zones.municipality(at(1.2, 0.5)), Some("East"));
        assert_eq!(zones.municipality(at(1.5, 0.5)), None); // in the hole
        assert_eq!(zones.municipality(at(5.0, 5.0)), None);
    }

    #[test]
    fn bundled_zones_cover_havana() {
        let zones = Zones::bundled().unwrap();
        assert_eq!(zones.0.len(), 15);
        // Belascoaín and San Lázaro, Plaza de la Catedral, Hotel Nacional
        // (Vedado) and the Havana airport.
        assert_eq!(
            zones.municipality(at(-82.3720, 23.1385)),
            Some("Centro Habana")
        );
        assert_eq!(
            zones.municipality(at(-82.3517, 23.1415)),
            Some("La Habana Vieja")
        );
        assert_eq!(
            zones.municipality(at(-82.3897, 23.1440)),
            Some("Plaza de la Revolución")
        );
        assert_eq!(zones.municipality(at(-82.4091, 22.9892)), Some("Boyeros"));
        // Varadero is outside the province.
        assert_eq!(zones.municipality(at(-81.2440, 23.1530)), None);
    }
}
